//! Tests for the English text frontend.
//!
//! `chunk_english` is checked against the reference `chunk_text_english` on a
//! corpus (`testdata/megatts3_text/chunks.json`, regenerated by
//! `tools/gen_megatts3_text_fixtures.py`). `normalize_english` has no reference
//! fixture, because WeTextProcessing needs pynini, which ships no macOS wheel:
//! its tests pin this port's own stated behavior, not FST output.

use std::path::{Path, PathBuf};

use super::text::{
    cardinal_words, chunk_english, ensure_english, normalize_english, ordinal_words,
};

fn testdata() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("testdata/megatts3_text")
}

#[test]
fn chunker_matches_the_reference_corpus() {
    let text = std::fs::read_to_string(testdata().join("chunks.json")).unwrap();
    let cases: Vec<serde_json::Value> = serde_json::from_str(&text).unwrap();
    assert!(cases.len() >= 70);
    for case in &cases {
        let input = case["text"].as_str().unwrap();
        let max = case["max_chars"].as_u64().unwrap() as usize;
        let want: Vec<String> = case["chunks"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| c.as_str().unwrap().to_string())
            .collect();
        assert_eq!(chunk_english(input, max), want, "text {input:?} max {max}");
    }
}

#[test]
fn chunker_basic_behavior() {
    assert!(chunk_english("", 130).is_empty());
    assert_eq!(chunk_english("Hello world.", 130), vec!["Hello world."]);
    // Sentences pack until the byte budget, then a new chunk starts.
    let packed = chunk_english("One. Two. Three. Four.", 10);
    assert_eq!(packed, vec!["One. Two.", "Three.", "Four."]);
    // Budget is UTF-8 bytes, not characters.
    let wide = chunk_english("\u{e9}\u{e9}\u{e9}. \u{e9}\u{e9}\u{e9}.", 8);
    assert_eq!(wide.len(), 2);
}

#[test]
fn language_gate() {
    assert!(ensure_english("Plain English, with caf\u{e9} and na\u{ef}ve accents; 123!").is_ok());
    assert!(ensure_english("").is_ok());
    for bad in [
        "\u{4f60}\u{597d}",
        "hello \u{4e16}\u{754c}",
        "\u{43f}\u{440}\u{438}\u{432}\u{435}\u{442}",
        "\u{3053}\u{3093}\u{306b}\u{3061}\u{306f}",
        "\u{c548}\u{b155}",
    ] {
        assert!(ensure_english(bad).is_err(), "{bad:?} accepted");
    }
    // Full-width punctuation alone is not a letter.
    assert!(ensure_english("Wide stop\u{3002}").is_ok());
}

#[test]
fn cardinal_and_ordinal_words() {
    for (n, want) in [
        (0, "zero"),
        (7, "seven"),
        (13, "thirteen"),
        (20, "twenty"),
        (21, "twenty one"),
        (100, "one hundred"),
        (101, "one hundred one"),
        (123, "one hundred twenty three"),
        (1000, "one thousand"),
        (1234, "one thousand two hundred thirty four"),
        (100_000, "one hundred thousand"),
        (1_000_001, "one million one"),
        (999_999_999_999, "nine hundred ninety nine billion nine hundred ninety nine million nine hundred ninety nine thousand nine hundred ninety nine"),
    ] {
        assert_eq!(cardinal_words(n), want, "{n}");
    }
    for (n, want) in [
        (1, "first"),
        (2, "second"),
        (3, "third"),
        (4, "fourth"),
        (5, "fifth"),
        (8, "eighth"),
        (9, "ninth"),
        (12, "twelfth"),
        (20, "twentieth"),
        (21, "twenty first"),
        (100, "one hundredth"),
        (1000, "one thousandth"),
    ] {
        assert_eq!(ordinal_words(n), want, "{n}");
    }
}

#[test]
fn normalizer_spells_supported_numbers() {
    for (input, want) in [
        ("I have 3 cats", "I have three cats"),
        (
            "It is 1,234 miles",
            "It is one thousand two hundred thirty four miles",
        ),
        ("Pi is 3.14.", "Pi is three point one four."),
        ("Grew 50% in 2 years", "Grew fifty percent in two years"),
        ("3.5% growth", "three point five percent growth"),
        (
            "the 1st, 2nd and 23rd",
            "the first, second and twenty third",
        ),
        ("It costs $5", "It costs five dollars"),
        ("only $1", "only one dollar"),
        ("$5.50 today", "five dollars fifty cents today"),
        ("$0.99", "ninety nine cents"),
        ("$0.01", "one cent"),
        ("$1,000", "one thousand dollars"),
        ("It is -5 degrees", "It is minus five degrees"),
        ("(-3)", "(minus three)"),
        ("0", "zero"),
        ("0.5", "zero point five"),
    ] {
        assert_eq!(normalize_english(input), want, "{input:?}");
    }
}

#[test]
fn normalizer_passes_through_what_it_cannot_read() {
    for same in [
        "COVID-19 spread",
        "3D printing and mp3 files",
        "Call 555-1234 now",
        "At 10:30 am",
        "On 5/3/2024",
        "2024-01-05",
        "Room 007",
        "US$5 only",
        "item #12",
        "v1.2.3",
        "1234567890123 digits",
        "5-10 people",
        "1,23 odd",
        "a-5 b",
        "1.2.3",
        "no numbers here",
    ] {
        assert_eq!(
            normalize_english(same),
            same,
            "{same:?} should pass through"
        );
    }
}

#[test]
fn normalizer_collapses_whitespace_only() {
    assert_eq!(normalize_english("  a \t b\n\n c  "), "a b c");
    assert_eq!(normalize_english(""), "");
    assert_eq!(normalize_english("   "), "");
    // Unicode text is left alone.
    assert_eq!(
        normalize_english("caf\u{e9} \u{201c}quoted\u{201d}"),
        "caf\u{e9} \u{201c}quoted\u{201d}"
    );
}

#[test]
fn normalizer_is_idempotent_on_its_output() {
    for input in [
        "I have 3 cats and $5.50",
        "the 1st of 10%",
        "-5 and 1,234.5",
    ] {
        let once = normalize_english(input);
        assert_eq!(normalize_english(&once), once, "{input:?}");
    }
}
